import { writeFileSync } from 'node:fs'
import { afterAll, test } from 'vitest'
const events: unknown[]=[]
test('sole recovered retry',{timeout:100,retry:1},async({signal,task})=>{
 const retry=task.result?.retryCount
 events.push(['body',retry,signal.aborted])
 if(!signal.aborted)await new Promise<void>(resolve=>signal.addEventListener('abort',()=>{events.push(['abort',retry]);resolve()},{once:true}))
 events.push(['settled',retry,signal.aborted])
})
afterAll(()=>writeFileSync(process.env.WS1_AUDIT_FILE!,JSON.stringify(events)))
